function finalPracticeBank(prefix, groups) {
  const rows = groups[0].flatMap((_, index) => groups.map(group => group[index]));
  return practiceSet(rows.map(([prompt, correct, distractors, explanation, passage], index) => {
    const answer = (index + Math.floor(index / 4)) % 4;
    const choices = [...distractors];
    choices.splice(answer, 0, correct);
    return [`${prefix}-${index + 1}`, prompt, choices, answer, explanation, passage];
  }));
}

